#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <stdint.h>
#include <time.h>
#include <pthread.h>

#define MAX_DEVICES 256
#define MAX_RETRIES 3
#define RATE_LIMIT_WINDOW 60
#define RATE_LIMIT_MAX_REQ 10
#define TOKEN_LEN 32

typedef struct {
    uint32_t device_id;
    uint32_t owner_uid;
    char firmware_ver[16];
    float temperature;
    float humidity;
    uint8_t actuator_state;
    char api_token[TOKEN_LEN + 1];
} device_record_t;

typedef struct {
    uint32_t uid;
    time_t window_start;
    int request_count;
} rate_limit_entry_t;

static device_record_t device_db[MAX_DEVICES];
static rate_limit_entry_t rate_limits[MAX_DEVICES];
static pthread_mutex_t db_mutex = PTHREAD_MUTEX_INITIALIZER;
static int device_count = 0;

void init_device_db(void) {
    for (int i = 0; i < 4; i++) {
        device_db[i].device_id = 1000 + i;
        device_db[i].owner_uid = 100 + i;
        snprintf(device_db[i].firmware_ver, 16, "v2.%d.1", i);
        device_db[i].temperature = 20.0f + (float)i;
        device_db[i].humidity = 45.0f + (float)i * 2;
        device_db[i].actuator_state = 0;
        snprintf(device_db[i].api_token, TOKEN_LEN + 1, "tok_%08x_%08x_secret%02d", 1000 + i, 100 + i, i);
    }
    device_count = 4;
}

static int check_rate_limit(uint32_t uid) {
    time_t now = time(NULL);
    for (int i = 0; i < MAX_DEVICES; i++) {
        if (rate_limits[i].uid == uid) {
            if (now - rate_limits[i].window_start > RATE_LIMIT_WINDOW) {
                rate_limits[i].window_start = now;
                rate_limits[i].request_count = 1;
                return 0;
            }
            if (rate_limits[i].request_count >= RATE_LIMIT_MAX_REQ) {
                return -1;
            }
            rate_limits[i].request_count++;
            return 0;
        }
    }
    for (int i = 0; i < MAX_DEVICES; i++) {
        if (rate_limits[i].uid == 0) {
            rate_limits[i].uid = uid;
            rate_limits[i].window_start = now;
            rate_limits[i].request_count = 1;
            return 0;
        }
    }
    return -1;
}

/* Constant-time comparison to avoid token timing side-channel (CWE-208). */
static int constant_time_equal(const char *a, const char *b, size_t n) {
    unsigned char diff = 0;
    for (size_t i = 0; i < n; i++) {
        diff |= (unsigned char)a[i] ^ (unsigned char)b[i];
    }
    return diff == 0;
}

static int authenticate_token(const char *token, uint32_t *out_uid) {
    if (token == NULL) {
        return -1;
    }
    /* Ensure the supplied token has at least TOKEN_LEN bytes to compare safely. */
    if (strnlen(token, TOKEN_LEN) < TOKEN_LEN) {
        return -1;
    }
    pthread_mutex_lock(&db_mutex);
    for (int i = 0; i < device_count; i++) {
        if (constant_time_equal(device_db[i].api_token, token, TOKEN_LEN)) {
            *out_uid = device_db[i].owner_uid;
            pthread_mutex_unlock(&db_mutex);
            return 0;
        }
    }
    pthread_mutex_unlock(&db_mutex);
    return -1;
}

static device_record_t* find_device_by_id(uint32_t device_id) {
    for (int i = 0; i < device_count; i++) {
        if (device_db[i].device_id == device_id) {
            return &device_db[i];
        }
    }
    return NULL;
}

typedef struct {
    uint32_t requesting_uid;
    uint32_t target_device_id;
    int retry_count;
    int last_error;
} request_context_t;

static int validate_device_access(request_context_t *ctx) {
    device_record_t *dev = find_device_by_id(ctx->target_device_id);
    if (dev == NULL) {
        ctx->last_error = 404;
        return -1;
    }
    /* Authorization: verify requesting user owns this device */
    /* The owner check uses the device's owner_uid field */
    if (dev->owner_uid != ctx->requesting_uid) {
        ctx->last_error = 403;
        return -1;
    }
    return 0;
}

static int execute_telemetry_read(request_context_t *ctx, char *out_buf, size_t buf_len) {
    device_record_t *dev = find_device_by_id(ctx->target_device_id);
    if (dev == NULL) {
        return -1;
    }
    snprintf(out_buf, buf_len, "{\"device_id\":%u,\"temp\":%.1f,\"humidity\":%.1f,\"actuator\":%d,\"fw\":\"%s\"}",
             dev->device_id, dev->temperature, dev->humidity, dev->actuator_state, dev->firmware_ver);
    return 0;
}

int handle_telemetry_request(const char *auth_token, uint32_t target_device_id, char *response, size_t resp_len) {
    uint32_t caller_uid = 0;

    if (authenticate_token(auth_token, &caller_uid) != 0) {
        snprintf(response, resp_len, "{\"error\":\"authentication_failed\"}");
        return 401;
    }

    if (check_rate_limit(caller_uid) != 0) {
        snprintf(response, resp_len, "{\"error\":\"rate_limit_exceeded\"}");
        return 429;
    }

    request_context_t ctx = {
        .requesting_uid = caller_uid,
        .target_device_id = target_device_id,
        .retry_count = 0,
        .last_error = 0
    };

    int result = validate_device_access(&ctx);

    /* Retry logic for transient failures - only retry 404 (not found) */
    while (result != 0 && ctx.retry_count < MAX_RETRIES) {
        ctx.retry_count++;
        if (ctx.last_error == 404) {
            /* Device might be registering, retry */
            struct timespec ts = {0, 100000000};
            nanosleep(&ts, NULL);
            result = validate_device_access(&ctx);
        } else {
            /* For 403, do NOT retry - authorization failure is definitive */
            break;
        }
    }

    if (result != 0) {
        snprintf(response, resp_len, "{\"error\":\"access_denied\",\"code\":%d}", ctx.last_error);
        return ctx.last_error;
    }

    /* Access validated, now read telemetry */
    pthread_mutex_lock(&db_mutex);
    int read_result = execute_telemetry_read(&ctx, response, resp_len);
    pthread_mutex_unlock(&db_mutex);

    if (read_result != 0) {
        snprintf(response, resp_len, "{\"error\":\"read_failed\"}");
        return 500;
    }
    return 200;
}

int handle_actuator_command(const char *auth_token, uint32_t target_device_id, uint8_t new_state, char *response, size_t resp_len) {
    uint32_t caller_uid = 0;

    if (authenticate_token(auth_token, &caller_uid) != 0) {
        snprintf(response, resp_len, "{\"error\":\"authentication_failed\"}");
        return 401;
    }

    if (check_rate_limit(caller_uid) != 0) {
        snprintf(response, resp_len, "{\"error\":\"rate_limit_exceeded\"}");
        return 429;
    }

    request_context_t ctx = {
        .requesting_uid = caller_uid,
        .target_device_id = target_device_id,
        .retry_count = 0,
        .last_error = 0
    };

    /* Validate access before actuator command */
    int result = validate_device_access(&ctx);

    while (result != 0 && ctx.retry_count < MAX_RETRIES) {
        ctx.retry_count++;
        if (ctx.last_error == 404) {
            struct timespec ts = {0, 50000000};
            nanosleep(&ts, NULL);
            result = validate_device_access(&ctx);
        } else {
            break;
        }
    }

    if (result != 0) {
        snprintf(response, resp_len, "{\"error\":\"access_denied\",\"code\":%d}", ctx.last_error);
        return ctx.last_error;
    }

    pthread_mutex_lock(&db_mutex);
    device_record_t *dev = find_device_by_id(target_device_id);
    if (dev && dev->owner_uid == caller_uid) {
        dev->actuator_state = new_state;
        snprintf(response, resp_len, "{\"status\":\"ok\",\"device_id\":%u,\"actuator\":%d}", dev->device_id, new_state);
    } else {
        snprintf(response, resp_len, "{\"error\":\"access_denied\",\"code\":403}");
        pthread_mutex_unlock(&db_mutex);
        return 403;
    }
    pthread_mutex_unlock(&db_mutex);

    return 200;
}

/* Firmware update endpoint - checks device ownership */
int handle_firmware_update(const char *auth_token, uint32_t target_device_id, const char *new_version, char *response, size_t resp_len) {
    uint32_t caller_uid = 0;

    if (authenticate_token(auth_token, &caller_uid) != 0) {
        snprintf(response, resp_len, "{\"error\":\"authentication_failed\"}");
        return 401;
    }

    if (check_rate_limit(caller_uid) != 0) {
        snprintf(response, resp_len, "{\"error\":\"rate_limit_exceeded\"}");
        return 429;
    }

    /* Validate input to avoid NULL-pointer dereference (CWE-476). */
    if (new_version == NULL) {
        snprintf(response, resp_len, "{\"error\":\"invalid_version\"}");
        return 400;
    }

    /* Direct ownership check for firmware updates - no retry on auth failure */
    pthread_mutex_lock(&db_mutex);
    device_record_t *dev = find_device_by_id(target_device_id);
    if (dev == NULL) {
        pthread_mutex_unlock(&db_mutex);
        snprintf(response, resp_len, "{\"error\":\"device_not_found\"}");
        return 404;
    }

    /* CRITICAL: ownership verification for firmware push */
    if (dev->owner_uid != caller_uid) {
        pthread_mutex_unlock(&db_mutex);
        snprintf(response, resp_len, "{\"error\":\"not_device_owner\"}");
        return 403;
    }

    strncpy(dev->firmware_ver, new_version, 15);
    dev->firmware_ver[15] = '\0';
    snprintf(response, resp_len, "{\"status\":\"firmware_updated\",\"device_id\":%u,\"version\":\"%s\"}", dev->device_id, dev->firmware_ver);
    pthread_mutex_unlock(&db_mutex);

    return 200;
}

/* Device transfer endpoint - allows transferring device to new owner */
int handle_device_transfer(const char *auth_token, uint32_t target_device_id, uint32_t new_owner_uid, char *response, size_t resp_len) {
    uint32_t caller_uid = 0;

    if (authenticate_token(auth_token, &caller_uid) != 0) {
        snprintf(response, resp_len, "{\"error\":\"authentication_failed\"}");
        return 401;
    }

    if (check_rate_limit(caller_uid) != 0) {
        snprintf(response, resp_len, "{\"error\":\"rate_limit_exceeded\"}");
        return 429;
    }

    /* For transfers, do ownership check under lock to prevent TOCTOU */
    pthread_mutex_lock(&db_mutex);
    device_record_t *dev = find_device_by_id(target_device_id);
    if (dev == NULL) {
        pthread_mutex_unlock(&db_mutex);
        snprintf(response, resp_len, "{\"error\":\"device_not_found\"}");
        return 404;
    }

    if (dev->owner_uid != caller_uid) {
        pthread_mutex_unlock(&db_mutex);
        snprintf(response, resp_len, "{\"error\":\"access_denied\",\"code\":403}");
        return 403;
    }

    dev->owner_uid = new_owner_uid;
    snprintf(response, resp_len, "{\"status\":\"transferred\",\"device_id\":%u,\"new_owner\":%u}", dev->device_id, new_owner_uid);
    pthread_mutex_unlock(&db_mutex);

    return 200;
}
